// Format Google News RSS items to standard structure
const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;

  // Get link from RSS feed
  const link = j.link || j.url || j.guid || '';
  if (!j.title || !link) continue;

  // Parse date from pubDate or isoDate
  let date = '';
  if (j.pubDate) {
    date = new Date(j.pubDate).toISOString().split('T')[0];
  } else if (j.isoDate) {
    date = new Date(j.isoDate).toISOString().split('T')[0];
  }

  // Clean description - remove HTML tags
  let description = (j.description || j.content || j.contentSnippet || '')
    .replace(/<[^>]*>/g, '')
    .substring(0, 300);

  results.push({
    json: {
      title: j.title,
      date: date,
      link: link,
      source: 'Google News',
      score: 0,
      description: description
    }
  });
}

return results.length > 0 ? results : [{ json: { empty: true, source: 'Google News' } }];

// Randomly select 7 articles with at least 2 from each source
// ONLY include articles from the last 60 days
const items = $input.all();
const seen = new Set();

// Calculate cutoff date (60 days ago)
const now = new Date();
const cutoffDate = new Date(now.getTime() - (60 * 24 * 60 * 60 * 1000));
const cutoffStr = cutoffDate.toISOString().split('T')[0];

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function sortByDateDesc(arr) {
  return arr.sort((a, b) => {
    if (!a.date) return 1;
    if (!b.date) return -1;
    return b.date.localeCompare(a.date);
  });
}

const bySource = { 'Reddit': [], 'Hacker News': [], 'Google News': [] };
let filteredCount = 0;

for (const item of items) {
  const j = item.json;
  if (j.empty || !j.title || !j.link || seen.has(j.link)) continue;
  seen.add(j.link);

  if (j.date && j.date < cutoffStr) {
    filteredCount++;
    continue;
  }

  const article = { title: j.title, date: j.date || '', link: j.link, source: j.source };
  if (bySource[j.source]) bySource[j.source].push(article);
}

for (const s in bySource) {
  bySource[s] = sortByDateDesc(bySource[s]);
  bySource[s] = shuffle(bySource[s].slice(0, 10));
}

const selected = [];
for (const s in bySource) {
  selected.push(...bySource[s].slice(0, 2));
  bySource[s] = bySource[s].slice(2);
}

const pool = shuffle([...bySource['Reddit'], ...bySource['Hacker News'], ...bySource['Google News']]);
while (selected.length < 7 && pool.length > 0) selected.push(pool.shift());

return [{ json: { 
  articles: shuffle(selected),
  cutoffDate: cutoffStr,
  articlesFiltered: filteredCount,
  articlesSelected: selected.length
} }];

