// Extract first 4 articles and create image prompts
const aiResponse = $input.item.json.output || $input.item.json.data || '';
let data;

try {
  const match = aiResponse.match(/\{[\s\S]*\}/);
  data = match ? JSON.parse(match[0]) : null;
  if (!data || !data.articles) throw new Error('No articles found');
} catch (e) {
  return [{ json: { error: 'Could not parse AI response', articles: [] } }];
}

const articlesWithImages = data.articles.map((article, index) => ({
  ...article,
  imageIndex: index,
  hasImage: index < 4,
  imagePrompt: index < 4 ? `Professional corporate illustration for: "${article.headline}". Style: photorealistic, . Aspect ratio 16:9.` : null
}));

return [{
  json: {
    ...data,
    articles: articlesWithImages,
    articlesForImages: articlesWithImages.filter(a => a.hasImage),
    newsletter_date: data.newsletter_date,
    intro_summary: data.intro_summary
  }
}];

// Extract only the first article's image prompt
const articles = $input.item.json.articles || [];
const firstArticle = articles.find(a => a.imageIndex === 0);

if (!firstArticle || !firstArticle.imagePrompt) {
  return [{ json: { prompt: 'Professional corporate illustration. Style: photorealistic, clean composition.' } }];
}

return [{ json: { prompt: firstArticle.imagePrompt, articleIndex: 0 } }];

// Prepare the 4 generated images for WordPress upload (one item per image)
const merged = $input.first();
const binaries = merged.binary || {};
const keys = ['image1','image2'];
const out = [];

for (let i = 0; i < keys.length; i++) {
  const k = keys[i];
  const b = binaries[k];
  if (!b) continue;

  const fileName = `ai-digest-img-${i+1}.png`;

  out.push({
    json: {
      image_index: i,
      filename: fileName,
    },
    binary: {
      data: {
        ...b,
        fileName,
      }
    }
  });
}

return out.length ? out : [{ json: { image_index: -1, filename: 'ai-digest-img-0.png', no_images: true } }];

// Collect WordPress media URLs back into an imageMap keyed by article index
const items = $input.all();
const imageMap = {};

for (const item of items) {
  const j = item.json || {};
  const url = j.source_url || (j.guid && j.guid.rendered) || (j.media_details && j.media_details.sizes && j.media_details.sizes.full && j.media_details.sizes.full.source_url);
  const slug = j.slug || '';
  const title = (j.title && (j.title.rendered || j.title)) || '';

  const m = slug.match(/ai-digest-img-(\d+)/i) || title.match(/ai-digest-img-(\d+)/i);
  if (!url || !m) continue;

  const idx = parseInt(m[1], 10) - 1;
  if (Number.isFinite(idx) && idx >= 0 && idx <= 3) {
    imageMap[`image_${idx}`] = url;
  }
}

return [{ json: { imageMap } }];

// Merge article data with uploaded image URLs
const articleData = $('Parse AI + Build Prompts').first().json;
const imageData = $input.item.json.imageMap || {};

const articlesWithImages = (articleData.articles || []).map((article, index) => {
  const url = imageData[`image_${index}`];
  if (index < 4 && url) {
    return {
      ...article,
      imageUrl: url,
      imageWidth: '180px',
      imageHeight: 'auto'
    };
  }
  return article;
});

return [{
  json: {
    articles: articlesWithImages,
    newsletter_date: articleData.newsletter_date,
    intro_summary: articleData.intro_summary
  }
}];

// Extract second article's image prompt
const articles = $input.item.json.articles || [];
const secondArticle = articles.find(a => a.imageIndex === 1);

if (!secondArticle || !secondArticle.imagePrompt) {
 return [{ json: { prompt: 'Professional corporate illustration. Style: photorealistic, clean composition.' } }];
}

return [{ json: { prompt: secondArticle.imagePrompt, articleIndex: 1 } }];

// Normalize Reddit RSS feed (.rss) to standard article structure
// RSS schema fields: title, link, pubDate, author, content, contentSnippet, id, isoDate
const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;
  const title = j.title || '';
  const link = j.link || j.guid || '';
  if (!title || !link) continue;

  // Skip Reddit's recurring auto-generated threads (low newsletter value)
  const lowerTitle = title.toLowerCase();
  if (lowerTitle.indexOf('daily thread') !== -1) continue;
  if (lowerTitle.indexOf('weekly thread') !== -1) continue;
  if (lowerTitle.indexOf('megathread') !== -1) continue;

  // Date from isoDate or pubDate
  let date = '';
  if (j.isoDate) date = new Date(j.isoDate).toISOString().split('T')[0];
  else if (j.pubDate) date = new Date(j.pubDate).toISOString().split('T')[0];

  // Description: prefer plain-text contentSnippet, strip Reddit boilerplate
  let description = j.contentSnippet || '';
  if (!description && j.content) {
    description = j.content.replace(/<[^>]*>/g, ' ');
  }
  description = description
    .replace(/submitted by[\s\S]*$/i, '')
    .replace(/\[link\]\s*\[comments\]/gi, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 300);

  results.push({
    json: {
      title: title,
      date: date,
      link: link,
      source: 'Reddit',
      score: 0,
      description: description
    }
  });
}

return results.length > 0 ? results : [{ json: { empty: true, source: 'Reddit' } }];

// Normalize Hacker News RSS feed (hnrss.org) to standard article structure
// hnrss schema fields: title, link, pubDate, author, content/contentSnippet, guid, isoDate, comments
const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json;
  const title = j.title || '';
  // Prefer the article link; fall back to guid (HN discussion URL)
  const link = j.link || j.guid || j.comments || '';
  if (!title || !link) continue;

  // Date from isoDate or pubDate
  let date = '';
  if (j.isoDate) date = new Date(j.isoDate).toISOString().split('T')[0];
  else if (j.pubDate) date = new Date(j.pubDate).toISOString().split('T')[0];

  // Description: strip HTML and hnrss boilerplate (Article URL / Comments URL / Points / # Comments)
  let description = j.contentSnippet || j.content || j.description || '';
  description = description
    .replace(/<[^>]*>/g, ' ')
    .replace(/Article URL:[\s\S]*$/i, '')
    .replace(/Comments URL:[\s\S]*$/i, '')
    .replace(/Points:[\s\S]*$/i, '')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 300);

  results.push({
    json: {
      title: title,
      date: date,
      link: link,
      source: 'Hacker News',
      score: 0,
      description: description
    }
  });
}

return results.length > 0 ? results : [{ json: { empty: true, source: 'Hacker News' } }];
